<template>
  <el-dialog
    title="上传全景图"
    :visible.sync="showDialogVisible"
    width="320px"
    :before-close="handleClose"
  >
    <div :class="uploadClass">
      <vr-upload
        ref="upload"
        mode="scene"
        tip="最大支持30m以内的图片"
        upload-class="upload-scene upload-scene-dialog"
        :maxFileSize="maxFileSize"
        @onSuccess="onUploadSuccess"
      />
    </div>

    <span slot="footer" class="dialog-footer">
      <el-button @click="cannel">取 消</el-button>
      <el-button
        type="primary"
        @click="nextOpt"
        :disabled="path === ''"
        :loading="nextOptLoading"
        v-if="scene === 'saveAndNext'"
      >下一步</el-button>
      <el-button v-else type="primary" @click="onSave" :disabled="path === ''">
        提 交
      </el-button>
    </span>
  </el-dialog>
</template>

<script>
import VrUpload from '@/components/VrUpload'
import { createProduct } from '../../api/vr'
// eslint-disable-next-line no-unused-vars
import { removeFiles } from '../../api/upload'
export default {
  name: 'SceneImgFormDialog',
  props: {
    uploadClass: String,
    scene: {
      type: String,
      default: 'saveAndNext'
    }
  },
  data() {
    return {
      showDialogVisible: false,
      fileId: 0,
      path: '',
      url: '',
      thumb: '',
      thumbUrl: '',
      maxFileSize: 30 * 1024 * 1024,
      nextOptLoading: false
    }
  },
  components: {
    VrUpload
  },
  watch: {},
  created() {
    this.showDialogVisible = this.dialogVisible
  },
  methods: {
    open() {
      this.showDialogVisible = true
    },
    cannel() {
      this.showDialogVisible = false
      this.$refs.upload.imageUrl = ''
    },
    handleClose() {
      this.$refs.upload.imageUrl = ''
      this.showDialogVisible = false
      // removeFiles({
      //   path: this.path,
      //   thumb: this.thumb
      // })
    },
    onUploadSuccess(result) {
      this.fileId = result.fileId
      this.path = result.path
      this.thumb = result.thumbPath
      this.url = result.url
      this.thumbUrl = result.thumbUrl
    },
    nextOpt() {
      if (this.path) {
        this.nextOptLoading = true
        createProduct({
          sceneImgs: [{
            path: this.path,
            thumb: this.thumb
          }]
        }).then(response => {
          this.nextOptLoading = false
          const { code, message, data: product } = response
          if (code === 0) {
            this.$router.push(`/diy/${product._id}`)
          } else {
            this.$message.error(message)
          }
        })
      }
    },
    onSave() {
      this.$emit('ok', {
        path: this.path,
        file_id: this.fileId,
        thumb_path: this.thumb,
        url: this.url,
        thumb_url: this.thumbUrl
      })
      this.cannel()
    }
  }
}
</script>

